package com.termux.app.workspace;
import android.app.*;import android.content.*;import android.content.pm.*;import android.speech.*;import android.widget.*;import android.os.*;import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadow.api.Shadow;import org.robolectric.shadows.ShadowAlertDialog;import java.util.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,shadows=AgentSpeechServiceTest.Engine.class) public class AgentSpeechServiceTest {
 @Implements(SpeechRecognizer.class) public static class Engine {static RecognitionListener listener;static int starts,destroys;@Implementation protected static SpeechRecognizer createSpeechRecognizer(Context c,ComponentName n){assertEquals("test.provider",n.getPackageName());return Shadow.newInstanceOf(SpeechRecognizer.class);}@Implementation protected void setRecognitionListener(RecognitionListener l){listener=l;}@Implementation protected void startListening(Intent i){starts++;}@Implementation protected void destroy(){destroys++;}}
 public static class Host extends Activity {@Override public void startActivityForResult(Intent i,int n){throw new ActivityNotFoundException();}}
 @Test public void serviceFallbackResultsCancelErrorAndChangedOwner(){Host a=Robolectric.buildActivity(Host.class).setup().get();Shadows.shadowOf((Application)a.getApplication()).grantPermissions(android.Manifest.permission.RECORD_AUDIO);ResolveInfo info=new ResolveInfo();info.serviceInfo=new ServiceInfo();info.serviceInfo.packageName="test.provider";info.serviceInfo.name="TestService";info.serviceInfo.enabled=true;info.serviceInfo.exported=true;info.serviceInfo.permission="android.permission.BIND_RECOGNITION_SERVICE";info.serviceInfo.applicationInfo=new ApplicationInfo();info.serviceInfo.applicationInfo.packageName="test.provider";Shadows.shadowOf(a.getPackageManager()).addResolveInfoForIntent(new Intent(RecognitionService.SERVICE_INTERFACE),info);
 EditText input=new EditText(a);input.setText("draft");String[] owner={"one"};List<String> notices=new ArrayList<>();AgentDictation d=new AgentDictation(a,input,()->owner[0],notices::add);
 d.start();AlertDialog chooser=ShadowAlertDialog.getLatestAlertDialog();chooser.getListView().performItemClick(chooser.getListView().getChildAt(0),0,0);assertEquals(1,Engine.starts);Bundle b=new Bundle();b.putStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION,new ArrayList<>(Arrays.asList("words")));Engine.listener.onResults(b);assertEquals("draft words",input.getText().toString());assertTrue(Engine.destroys>0);
 d.start();chooser=ShadowAlertDialog.getLatestAlertDialog();chooser.getListView().performItemClick(null,0,0);owner[0]="two";Engine.listener.onResults(b);assertEquals("draft words",input.getText().toString());assertEquals(1,notices.size());
 d.start();chooser=ShadowAlertDialog.getLatestAlertDialog();chooser.getListView().performItemClick(null,0,0);Engine.listener.onError(SpeechRecognizer.ERROR_NETWORK);assertEquals("draft words",input.getText().toString());assertEquals(2,notices.size());
 d.start();chooser=ShadowAlertDialog.getLatestAlertDialog();chooser.getListView().performItemClick(null,0,0);ShadowAlertDialog.getLatestAlertDialog().cancel();Shadows.shadowOf(Looper.getMainLooper()).idle();Engine.listener.onResults(b);assertEquals("draft words",input.getText().toString());
 }
}
